package com.nequard.events;
import org.springframework.http.MediaType;import org.springframework.web.bind.annotation.*;import org.springframework.web.servlet.mvc.method.annotation.SseEmitter;import java.io.IOException;import java.util.concurrent.CopyOnWriteArrayList;
@RestController @RequestMapping("/api/v1/events") public class EventController{private final CopyOnWriteArrayList<SseEmitter> clients=new CopyOnWriteArrayList<>();@GetMapping(value="/stream",produces=MediaType.TEXT_EVENT_STREAM_VALUE)public SseEmitter stream(){SseEmitter e=new SseEmitter(0L);clients.add(e);e.onCompletion(()->clients.remove(e));e.onTimeout(()->clients.remove(e));return e;}@PostMapping("/publish")public int publish(@RequestBody Object event){int sent=0;for(SseEmitter e:clients)try{e.send(SseEmitter.event().name("nequard-event").data(event));sent++;}catch(IOException ex){clients.remove(e);}return sent;}}
